INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('yaganar', 'Yaganar', 'humanoid', 'rifts', 1, 'Any; usually Principled or Scrupulous when first found, and many stay good, though some drift to Selfish or Evil with experience.', '{"IQ":"2D6+4","ME":"2D6+3","MA":"2D6+10","PS":"2D6+11","PP":"2D6+3","PE":"1D6+12","PB":"1D6+6","Spd":"3D6+10"}', NULL, NULL, 'PE+8', '1D6x10+20', NULL, 'A Mega-Damage being; the row rolls an Air Yaganar at level one. M.D.C. is the P.E. number plus a per-level amount from level one: +8 Air, +12 Earth, +9 Fire, +10 Water/Ice, with more at levels 1 (Earth +10), 3 (Earth +10), 6 (Air +25, Earth +50, Fire +30, Water +40), 10 (Air +20, Earth +30, Fire +25, Water +25) and 12 (+20). P.P.E. Air and Fire 1D6x10+20 (+8 per level), Earth 1D6x10+40 (+10 per level), Water 1D6x10+30 (+9 per level), plus level 7 (+25 Air and Fire, +30 Water, +40 Earth), level 10 (+20 Air and Fire, +40 Earth, +25 Water) and level 11 (1D6x10+10). Spd is 3D6, +10 for Air and +8 for Fire. P.S. and P.E. are Supernatural. M.D.C. and M.D. become S.D.C. and S.D.C. damage in S.D.C. settings.', NULL, 8, '{"initiative":1,"dodge":1}', 'Attacks per melee from Hand to Hand: Expert. The combat figures are the Air Yaganar''s level-one bonuses (+6 P.P., +1 initiative, +1 dodge). Level one gives Earth +6 P.S., +1 P.P. and +10 M.D.C.; Fire +4 P.P., +1 attack and +1 strike; Water +3 P.P. and +1 roll with impact. Every later level adds element powers and bonuses, listed on the Yaganar class. Horror Factor rises to 11 at level 12 and 13 at level 13.', 'All: Hand to Hand: Expert, Land Navigation +20%, Physical Labor, Wilderness Survival +30%, and Russian, Euro and Chinese spoken at 92%; cannot learn to read or write. Air adds Acrobatics +20%, Escape Artist +15%, Prowl +15%, Sing +15%, Wardrobe and Grooming +10% and two W.P.s; Earth adds Camouflage +20%, Gardening +30%, Gemology +20%, Holistic Medicine +15% and two W.P.s; Fire adds Climbing +20%, Detect Concealment +10%, Firefighting +30% and three W.P.s; Water adds Dowsing +30%, Fishing +30%, Swimming +30%, every Boat pilot skill +10% and one W.P. Two more skills at levels 2, 5 and 9 from Cowboy, Domestic, Weapon Proficiencies and Wilderness. No secondary skills. These are on the Yaganar class.', 'Supernatural strength and endurance; nightvision to 200 feet (61 m); immune to disease; takes half damage from heat, cold, fire and exposure; understands every language at 50% by magic. Needs only 1D4+1 hours of sleep and half a human''s food and water, but still breathes, so gases, drugs and poisons work on it. Heals 3D6 M.D.C. plus 1 per level each day, twice that on a ley line, at a nexus or in the Elemental planes. As it levels it gains control of its element (level 2), an element immunity (3), elemental blasts at will (5: Air lightning 4D6, Earth stone shard 3D6+2, Fire bolt 3D6+2, Water ice shard 3D6+1), flight, air walking, lava walking or wave riding (6 and 9), Elemental Warlock spells (7, 10, 11, 14), Bio-Regeneration (7 and 12), summoned Elemental Armor (8), elemental fists or weapons (9) and, at 15, armor that grows stronger before it vanishes from the world. Heat and fire do double damage to a Water Yaganar, cold and ice double to a Fire Yaganar.', 'From level 7, Elemental (Warlock) spells of its own element only: 1D4+4 of levels 1-4 at level 7, four of levels 1-5 at level 10, 1D4+2 of levels 1-8 at level 11 and four of levels 1-8 at level 14. Its control, blasts and armor are natural abilities, not spells.', 'None.', '6 feet to 7 feet 4 inches (1.8 to 2.4 m); 8 inches taller at level 12 and 3D4 inches more at level 14', '115 to 200 lbs (52 to 90 kg) at first, tall and gaunt; +30% at level 12 and again at level 14 (Earth Elemental Armor adds half its body weight, Ice armor 40%)', 'Unknown. The race page gives 1D6x10+12 years in its near-human form and 1D4x10+6 more in its elemental form; the stat block gives 1D4x10+20 years from its first appearance, or until it reaches level 15, whichever comes first. At level 15 it vanishes within days to years.', 'Russia and Scandinavia, less often the rest of eastern and northern Europe; seen most along St. Peter''s Spine and in the wilds around Moscow. Usually travels with a group of humans.', 'Drawn to humans, Cold Born, Wolverine People, Warlocks, Elemental Fusionists, Druids, Spirits of Light and others who work Elemental magic or live close to nature; friendly with other D-Bees.', 'Distrusts Splugorth, demons and other evil supernatural beings, Necromancers, Shifters, Slavers and most magic users it has not befriended; attacks anyone who threatens a friend. Russian Fire Sorcerers hunt it as an abomination, and true Elementals single it out in a fight.', 'No O.C.C.; it lives by its racial and element skills and works as a soldier, guard, scout, laborer or farmer. Playable as the Yaganar class. Cybernetics and bionics are impossible. Slave value 2D6x10,000 credits.', 'A D-Bee that Russians take for an Ice Elemental, demon or walking corpse. Each appears naked and filthy at the edge of a field or road with no memory of anything before, gaunt, white-haired and cracked-skinned, with solid-colored eyes that seem to seethe. Each carries one element - air, earth, fire or water - and folk tales guess at it from skin and hair color. The Sovietski sends the ones it finds to collective farms and factories, then to the army or police once indoctrinated, where officers often treat them as attack dogs. Eager, childlike and loyal at first, a Yaganar grows quieter, stronger and less human with every level, until at the height of its power it vanishes, leaving a trace of its element behind.', 'Rifts World Book 36: Sovietski p.73-78');

