('creature', 'yaganar', 'Lightning bolt (Air, level 5)', '4D6', 1, '120 feet (36.6 m) per level', 'Air Yaganar from level 5; +1 M.D. per level past 5, +2D6 from level 14. One melee attack, no P.P.E.', 0),
('creature', 'yaganar', 'Stone shard (Earth, level 5)', '3D6+2', 1, '80 feet (24.4 m) per level', 'Earth Yaganar from level 5; +2D6 from level 14. One melee attack, no P.P.E.', 1),
('creature', 'yaganar', 'Fire bolt (Fire, level 5)', '3D6+2', 1, '100 feet (30.5 m) per level', 'Fire Yaganar from level 5; +1 M.D. per level past 5, +2D6 from level 14. One melee attack, no P.P.E.', 2),
('creature', 'yaganar', 'Ice shard (Water, level 5)', '3D6+1', 1, '90 feet (27.4 m) per level', 'Water Yaganar from level 5; +2D6 from level 14. One melee attack, no P.P.E.', 3),
('creature', 'yaganar', 'Elemental fists (level 9)', '2D6', 1, NULL, 'Added to Supernatural P.S. punch damage from level 9: Air electric and Earth stone fists +2D6, Fire +2D6+3, Water ice fists +1D6. Earth and Water may form a stone or ice weapon instead (2D6 plus P.S. damage, thrown 100 or 80 feet per level).', 4);

