SELECT 'all 1 creatures are in' AS assertion, count(*) AS got, 1 AS want
  FROM creatures WHERE slug IN ('yaganar');
SELECT 'and 1 of them are playable' AS assertion, count(*) AS got, 1 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('yaganar');
SELECT 'the creatures carry 5 attacks' AS assertion, count(*) AS got, 5 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('yaganar');

